CREATE INDEX `log_changes_issue_revoke_idx` ON `log_changes` (`at`,`number`) WHERE ((instr("log_changes"."payload", '{"caller":"') = 1 AND instr("log_changes"."payload", '"issue":{"by":"') > 0) OR (instr("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND instr("log_changes"."payload", '"reason":"revoke"') > 0) OR (instr("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND instr("log_changes"."payload", '"reason":"sign_out"') > 0));--> statement-breakpoint
CREATE INDEX `log_changes_issue_revoke_actor_idx` ON `log_changes` (`actor`,`at`,`number`) WHERE ((instr("log_changes"."payload", '{"caller":"') = 1 AND instr("log_changes"."payload", '"issue":{"by":"') > 0) OR (instr("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND instr("log_changes"."payload", '"reason":"revoke"') > 0) OR (instr("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND instr("log_changes"."payload", '"reason":"sign_out"') > 0));